  [11711] = { "Affligge il bersaglio con l'agonia, infliggendo $N1 danni da ombra in $D1. All'inizio i danni sono inflitti lentamente e aumentano man mano che l'anatema si avvicina alla sua durata massima. Su un bersaglio può essere attivo solo un anatema per Stregone alla volta.", { "$N1 danni da ombra in $D1.", shape = { "2/1" } }, 0xd5b9a42b, 0x0adb28cc, "uu" },
  [11712] = { "Affligge il bersaglio con l'agonia, infliggendo $N1 danni da ombra in $D1. All'inizio i danni sono inflitti lentamente e aumentano man mano che l'anatema si avvicina alla sua durata massima. Su un bersaglio può essere attivo solo un anatema per Stregone alla volta.", { "$N1 danni da ombra in $D1.", shape = { "2/1" } }, 0xd5b9a42b, 0x0adb28cc, "uu" },
